describe("WeightBasedShippingCalculator", () => {
  const brackets = [
    { upToGrams: 500, costCents: 300 },
    { upToGrams: 1000, costCents: 600 },
    { upToGrams: 5000, costCents: 1200 },
  ];

  it("throws when brackets is empty", () => {
    expect(() => new WeightBasedShippingCalculator([])).toThrow(
      "at least one weight bracket is required",
    );
  });

  it("throws on invalid bracket upToGrams", () => {
    expect(
      () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 100 }]),
    ).toThrow(RangeError);
    expect(
      () => new WeightBasedShippingCalculator([{ upToGrams: -1, costCents: 100 }]),
    ).toThrow(RangeError);
  });

  it("throws on invalid bracket costCents", () => {
    expect(
      () => new WeightBasedShippingCalculator([{ upToGrams: 100, costCents: -1 }]),
    ).toThrow(RangeError);
  });

  it("throws on invalid overflowCostCents", () => {
    expect(
      () =>
        new WeightBasedShippingCalculator(
          [{ upToGrams: 100, costCents: 100 }],
          -5,
        ),
    ).toThrow(RangeError);
  });

  it("returns 0 for empty cart", () => {
    const calc = new WeightBasedShippingCalculator(brackets);
    expect(calc.computeShippingCents([], 5000)).toBe(0);
  });

  it("returns 0 when total weight is 0", () => {
    const calc = new WeightBasedShippingCalculator(brackets);
    expect(
      calc.computeShippingCents([makeLine("a", undefined, 2)], 5000),
    ).toBe(0);
  });

  it.each([
    { weight: 200, expected: 300 },
    { weight: 500, expected: 300 },
    { weight: 501, expected: 600 },
    { weight: 1000, expected: 600 },
    { weight: 4999, expected: 1200 },
    { weight: 5000, expected: 1200 },
  ])(
    "selects correct bracket for weight=$weight → $expected cents",
    ({ weight, expected }) => {
      const calc = new WeightBasedShippingCalculator(brackets);
      const lines = [makeLine("a", weight, 1)];
      expect(calc.computeShippingCents(lines, 1000)).toBe(expected);
    },
  );

  it("uses heaviest bracket cost as overflow when no overflowCostCents set", () => {
    const calc = new WeightBasedShippingCalculator(brackets);
    const lines = [makeLine("a", 6000, 1)];
    expect(calc.computeShippingCents(lines, 1000)).toBe(1200);
  });

  it("uses overflowCostCents when set and weight exceeds all brackets", () => {
    const calc = new WeightBasedShippingCalculator(brackets, 2000);
    const lines = [makeLine("a", 6000, 1)];
    expect(calc.computeShippingCents(lines, 1000)).toBe(2000);
  });

  it("sorts brackets internally regardless of input order", () => {
    const unordered = [
      { upToGrams: 1000, costCents: 600 },
      { upToGrams: 500, costCents: 300 },
    ];
    const calc = new WeightBasedShippingCalculator(unordered);
    expect(calc.computeShippingCents([makeLine("a", 400, 1)], 0)).toBe(300);
    expect(calc.computeShippingCents([makeLine("a", 700, 1)], 0)).toBe(600);
  });

  it("multiplies weight by quantity", () => {
    const calc = new WeightBasedShippingCalculator(brackets);
    // 200g * 3 = 600g → second bracket (501-1000) = 600
    const lines = [makeLine("a", 200, 3)];
    expect(calc.computeShippingCents(lines, 1000)).toBe(600);
  });
});

