    await expect(cart.checkout({ inventoryChecker })).rejects.toThrow("low stock");
  });

  it("throws InventoryError when availableQuantity < requested", async () => {
    const cart = new Cart();
    cart.add(productA, 10);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 3,
      } satisfies InventoryDecision),
    };
    await expect(cart.checkout({ inventoryChecker })).rejects.toThrow(InventoryError);
  });

  it("passes when inventory is sufficient", async () => {
    const cart = new Cart();
    cart.add(productA, 2);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 10,
      } satisfies InventoryDecision),
    };
    const result = await cart.checkout({ inventoryChecker });
    expect(result.totals.subtotalCents).toBe(2000);
  });

  it("uses asyncTaxProvider for tax when supplied", async () => {
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.08),
    };
    const cart = new Cart({ region: "US-TX" });
    cart.add(productA, 1); // subtotal=1000, no discount → taxable=1000
    const result = await cart.checkout({ asyncTaxProvider });
    expect(result.totals.taxCents).toBe(80); // floor(1000 * 0.08)
    expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US-TX");
  });

  it("combines priceFetcher + inventoryChecker + asyncTaxProvider", async () => {
    const cart = new Cart();
    cart.add(productA, 2);
    cart.add(productB, 1);

    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn()
        .mockResolvedValueOnce(1200) // a → 1200
        .mockResolvedValueOnce(3000), // b → 3000
    };
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 100 }),
    };
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };

    const result = await cart.checkout({ priceFetcher, inventoryChecker, asyncTaxProvider });
    // subtotal: 1200*2 + 3000*1 = 5400, tax: floor(5400 * 0.1) = 540
    expect(result.totals.subtotalCents).toBe(5400);
    expect(result.totals.taxCents).toBe(540);
  });

  it("generates default error message when no reason provided", async () => {
    const cart = new Cart();
    cart.add(productA, 5);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: false,
      } satisfies InventoryDecision),
    };
    try {
      await cart.checkout({ inventoryChecker });
    } catch (e) {
      expect(e).toBeInstanceOf(InventoryError);
      expect((e as InventoryError).message).toContain("insufficient stock");
      expect((e as InventoryError).productId).toBe("a");
    }
  });

  it("checks inventory for each line sequentially", async () => {
    const cart = new Cart();
    cart.add(productA, 1);
    cart.add(productB, 1);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn()
        .mockResolvedValueOnce({ available: true, availableQuantity: 10 })
        .mockResolvedValueOnce({ available: false, reason: "discontinued" }),
    };
    await expect(cart.checkout({ inventoryChecker })).rejects.toThrow("discontinued");
    expect(inventoryChecker.check).toHaveBeenCalledTimes(2);
  });
});

import { describe, it, expect } from "vitest";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
  CompositeDiscountPolicy,
} from "../src/pricing.ts";

describe("NoDiscountPolicy", () => {
  const policy = new NoDiscountPolicy();

  it("returns 0 for any subtotal", () => {
    expect(policy.computeDiscountCents(10000)).toBe(0);
    expect(policy.computeDiscountCents(0)).toBe(0);
    expect(policy.computeDiscountCents(1)).toBe(0);
  });
});

describe("PercentageDiscountPolicy", () => {
  it("throws on invalid percent values", () => {
    expect(() => new PercentageDiscountPolicy(-1)).toThrow(RangeError);
    expect(() => new PercentageDiscountPolicy(101)).toThrow(RangeError);
    expect(() => new PercentageDiscountPolicy(NaN)).toThrow(RangeError);
    expect(() => new PercentageDiscountPolicy(Infinity)).toThrow(RangeError);
  });

  it("accepts boundary values 0 and 100", () => {
    expect(new PercentageDiscountPolicy(0).computeDiscountCents(5000)).toBe(0);
    expect(new PercentageDiscountPolicy(100).computeDiscountCents(5000)).toBe(5000);
  });

  it.each([
    { percent: 10, subtotal: 10000, expected: 1000 },
    { percent: 15, subtotal: 9999, expected: 1499 },
    { percent: 33, subtotal: 100, expected: 33 },
    { percent: 50, subtotal: 1, expected: 0 },
  ])(
    "computes $percent% of $subtotal = $expected (rounded down)",
    ({ percent, subtotal, expected }) => {
      const policy = new PercentageDiscountPolicy(percent);
      expect(policy.computeDiscountCents(subtotal)).toBe(expected);
    },
  );

  it("returns 0 when subtotal is 0 or negative", () => {
    const policy = new PercentageDiscountPolicy(20);
    expect(policy.computeDiscountCents(0)).toBe(0);
    expect(policy.computeDiscountCents(-500)).toBe(0);
  });
});

describe("FixedAmountDiscountPolicy", () => {
  it("throws on invalid amountCents", () => {
    expect(() => new FixedAmountDiscountPolicy(-1)).toThrow(RangeError);
    expect(() => new FixedAmountDiscountPolicy(1.5)).toThrow(RangeError);
  });

  it("returns the fixed amount when subtotal exceeds it", () => {
    const policy = new FixedAmountDiscountPolicy(500);
    expect(policy.computeDiscountCents(1000)).toBe(500);
  });

  it("caps at subtotal when fixed amount exceeds subtotal", () => {
    const policy = new FixedAmountDiscountPolicy(2000);
    expect(policy.computeDiscountCents(500)).toBe(500);
  });

  it("returns 0 when subtotal is 0 or negative", () => {
    const policy = new FixedAmountDiscountPolicy(500);
    expect(policy.computeDiscountCents(0)).toBe(0);
    expect(policy.computeDiscountCents(-100)).toBe(0);
  });

  it("accepts 0 as a valid amount", () => {
    const policy = new FixedAmountDiscountPolicy(0);
    expect(policy.computeDiscountCents(5000)).toBe(0);
  });
});

describe("CompositeDiscountPolicy", () => {
  it("throws when given empty policies array", () => {
    expect(() => new CompositeDiscountPolicy([])).toThrow(
      "CompositeDiscountPolicy requires at least one policy",
    );
  });

  describe("sum mode", () => {
    it("sums discounts from all child policies against original subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(200)],
        "sum",
      );
      // 10% of 5000 = 500, plus fixed 200 = 700
      expect(composite.computeDiscountCents(5000)).toBe(700);
    });

    it("ignores negative child results (clamps each to 0)", () => {
      const negativePolicy = { computeDiscountCents: () => -100 };
      const composite = new CompositeDiscountPolicy(
        [negativePolicy, new FixedAmountDiscountPolicy(300)],
        "sum",
      );
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("returns 0 when subtotal is 0 or negative", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
      expect(composite.computeDiscountCents(-100)).toBe(0);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially to remaining subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new PercentageDiscountPolicy(10)],
        "chain",
      );
      // First: 10% of 10000 = 1000, remaining = 9000
      // Second: 10% of 9000 = 900, total discount = 1900
      expect(composite.computeDiscountCents(10000)).toBe(1900);
    });

    it("stops accumulating once remaining reaches 0", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(800), new FixedAmountDiscountPolicy(500)],
        "chain",
      );
      // First takes 800 from 1000 (remaining=200), second takes min(500,200)=200
      expect(composite.computeDiscountCents(1000)).toBe(1000);
    });

    it("clamps negative child results to 0 per step", () => {
      const negativePolicy = { computeDiscountCents: () => -50 };
      const composite = new CompositeDiscountPolicy(
        [negativePolicy, new FixedAmountDiscountPolicy(100)],
        "chain",
      );
      // negative clamped to 0, then 100 from 1000
      expect(composite.computeDiscountCents(1000)).toBe(100);
    });

    it("returns 0 when subtotal is 0 or negative", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });
  });

  it("defaults to sum mode when not specified", () => {
    const composite = new CompositeDiscountPolicy([
      new FixedAmountDiscountPolicy(100),
      new FixedAmountDiscountPolicy(200),
    ]);
    expect(composite.computeDiscountCents(5000)).toBe(300);
  });
});

