  PriceFetcher,
  InventoryChecker,
  InventoryDecision,
} from "../src/inventory.ts";
import { InventoryError } from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";

const productA: Product = { id: "a", name: "Widget", unitPriceCents: 1000, weightGrams: 200 };
const productB: Product = { id: "b", name: "Gadget", unitPriceCents: 2500, weightGrams: 500 };

describe("Cart - basic operations", () => {
  let cart: Cart;

  beforeEach(() => {
    cart = new Cart();
  });

  it("starts empty", () => {
    expect(cart.itemCount).toBe(0);
    expect(cart.snapshot()).toEqual([]);
  });

  it("adds a product", () => {
    cart.add(productA, 3);
    expect(cart.itemCount).toBe(3);
  });

  it("accumulates quantity for same product", () => {
    cart.add(productA, 2);
    cart.add(productA, 3);
    expect(cart.itemCount).toBe(5);
    expect(cart.snapshot()).toHaveLength(1);
  });

  it("throws on non-positive quantity", () => {
    expect(() => cart.add(productA, 0)).toThrow(RangeError);
    expect(() => cart.add(productA, -1)).toThrow(RangeError);
    expect(() => cart.add(productA, 1.5)).toThrow(RangeError);
  });

  it("throws on negative unit price", () => {
    const bad: Product = { id: "x", name: "Bad", unitPriceCents: -10 };
    expect(() => cart.add(bad, 1)).toThrow(RangeError);
  });

  it("removes a product", () => {
    cart.add(productA, 1);
    expect(cart.remove("a")).toBe(true);
    expect(cart.itemCount).toBe(0);
  });

  it("returns false when removing non-existent product", () => {
    expect(cart.remove("nonexistent")).toBe(false);
  });

  it("updates quantity", () => {
    cart.add(productA, 5);
    cart.updateQuantity("a", 2);
    expect(cart.itemCount).toBe(2);
  });

  it("removes product when updating to 0", () => {
    cart.add(productA, 3);
    cart.updateQuantity("a", 0);
    expect(cart.itemCount).toBe(0);
    expect(cart.snapshot()).toHaveLength(0);
  });

  it("throws on invalid quantity in updateQuantity", () => {
    cart.add(productA, 1);
    expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
    expect(() => cart.updateQuantity("a", 1.5)).toThrow(RangeError);
  });

  it("throws when updating non-existent product", () => {
    expect(() => cart.updateQuantity("missing", 5)).toThrow(
      "Product missing is not in the cart",
    );
  });

  it("clears all items", () => {
    cart.add(productA, 2);
    cart.add(productB, 1);
    cart.clear();
    expect(cart.itemCount).toBe(0);
  });

  it("snapshot returns a deep copy", () => {
    cart.add(productA, 1);
    const snap = cart.snapshot();
    snap[0].product.unitPriceCents = 9999;
    snap[0].quantity = 99;
    expect(cart.snapshot()[0].product.unitPriceCents).toBe(1000);
    expect(cart.snapshot()[0].quantity).toBe(1);
  });
});

describe("Cart - totals with mocked seams", () => {
  it("computes subtotal from line prices × quantities", () => {
    const cart = new Cart();
    cart.add(productA, 2); // 2000
    cart.add(productB, 1); // 2500
    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(4500);
  });

  it("applies discount policy and clamps to [0, subtotal]", () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(500),
    };
    const cart = new Cart({ discountPolicy: discount });
    cart.add(productA, 1); // subtotal = 1000
    const totals = cart.totals();
    expect(totals.discountCents).toBe(500);
    expect(totals.totalCents).toBe(500); // 1000 - 500
  });

  it("clamps over-subtotal discount to subtotal", () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(99999),
    };
    const cart = new Cart({ discountPolicy: discount });
    cart.add(productA, 1);
    expect(cart.totals().discountCents).toBe(1000);
  });

  it("clamps negative discount to 0", () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(-500),
    };
    const cart = new Cart({ discountPolicy: discount });
    cart.add(productA, 1);
    expect(cart.totals().discountCents).toBe(0);
  });

  it("computes tax on discounted subtotal", () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: () => 200,
    };
    const tax: TaxCalculator = {
      computeTaxCents: vi.fn((taxable, _region) => Math.floor(taxable * 0.1)),
    };
    const cart = new Cart({ discountPolicy: discount, taxCalculator: tax });
    cart.add(productA, 1); // subtotal=1000, discount=200, taxable=800
    const totals = cart.totals();
    expect(totals.taxCents).toBe(80);
    expect(tax.computeTaxCents).toHaveBeenCalledWith(800, "US");
  });

  it("clamps negative tax to 0", () => {
    const tax: TaxCalculator = {
      computeTaxCents: () => -100,
    };
    const cart = new Cart({ taxCalculator: tax });
    cart.add(productA, 1);
    expect(cart.totals().taxCents).toBe(0);
  });

  it("computes shipping on discounted subtotal", () => {
    const shipping: ShippingCalculator = {
      computeShippingCents: vi.fn((_lines, subtotal) => (subtotal >= 5000 ? 0 : 999)),
    };
    const cart = new Cart({ shippingCalculator: shipping });
    cart.add(productA, 1); // subtotal=1000, discounted=1000
    expect(cart.totals().shippingCents).toBe(999);
  });

  it("clamps negative shipping to 0", () => {
    const shipping: ShippingCalculator = {
      computeShippingCents: () => -50,
    };
    const cart = new Cart({ shippingCalculator: shipping });
    cart.add(productA, 1);
    expect(cart.totals().shippingCents).toBe(0);
  });

  it("total = discountedSubtotal + tax + shipping", () => {
    const discount: DiscountPolicy = { computeDiscountCents: () => 100 };
    const tax: TaxCalculator = { computeTaxCents: () => 50 };
    const shipping: ShippingCalculator = { computeShippingCents: () => 200 };
    const cart = new Cart({
      discountPolicy: discount,
      taxCalculator: tax,
      shippingCalculator: shipping,
    });
    cart.add(productA, 1); // subtotal=1000, discount=100, discounted=900
    const totals = cart.totals();
    expect(totals.totalCents).toBe(900 + 50 + 200);
  });

  it("uses 'US' as default region", () => {
    const tax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(0),
    };
    const cart = new Cart({ taxCalculator: tax });
    cart.add(productA, 1);
    cart.totals();
    expect(tax.computeTaxCents).toHaveBeenCalledWith(expect.any(Number), "US");
  });

  it("passes custom region to tax calculator", () => {
    const tax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(0),
    };
    const cart = new Cart({ taxCalculator: tax, region: "FR" });
    cart.add(productA, 1);
    cart.totals();
    expect(tax.computeTaxCents).toHaveBeenCalledWith(expect.any(Number), "FR");
  });

  it("empty cart returns all zeros", () => {
    const cart = new Cart();
    const totals = cart.totals();
    expect(totals).toEqual({
      subtotalCents: 0,
      discountCents: 0,
      taxCents: 0,
      shippingCents: 0,
      totalCents: 0,
    });
  });
});

describe("Cart - checkout()", () => {
  it("returns totals and lines for simple checkout", async () => {
    const cart = new Cart();
    cart.add(productA, 2);
    const result = await cart.checkout();
    expect(result.totals.subtotalCents).toBe(2000);
    expect(result.lines).toHaveLength(1);
    expect(result.lines[0].quantity).toBe(2);
  });

  it("refreshes prices via priceFetcher", async () => {
    const cart = new Cart();
    cart.add(productA, 1);
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(1500),
    };
    const result = await cart.checkout({ priceFetcher });
    expect(result.totals.subtotalCents).toBe(1500);
    expect(priceFetcher.fetchPriceCents).toHaveBeenCalledWith("a");
  });

  it("throws InventoryError when item is unavailable", async () => {
    const cart = new Cart();
    cart.add(productA, 5);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: false,
        availableQuantity: 2,
        reason: "low stock",
      } satisfies InventoryDecision),
    };
    await expect(cart.checkout({ inventoryChecker })).rejects.toThrow(InventoryError);
    await expect(cart.checkout({ inventoryChecker })).rejects.toThrow("low stock");
  });

  it("throws InventoryError when availableQuantity < requested", async () => {
    const cart = new Cart();
    cart.add(productA, 10);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 3,
      } satisfies InventoryDecision),
    };
    await expect(cart.checkout({ inventoryChecker })).rejects.toThrow(InventoryError);
  });

  it("passes when inventory is sufficient", async () => {
    const cart = new Cart();
    cart.add(productA, 2);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 10,
      } satisfies InventoryDecision),
    };
    const result = await cart.checkout({ inventoryChecker });
    expect(result.totals.subtotalCents).toBe(2000);
  });

  it("uses asyncTaxProvider for tax when supplied", async () => {
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.08),
    };
    const cart = new Cart({ region: "US-TX" });
    cart.add(productA, 1); // subtotal=1000, no discount → taxable=1000
    const result = await cart.checkout({ asyncTaxProvider });
    expect(result.totals.taxCents).toBe(80); // floor(1000 * 0.08)
    expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US-TX");
  });

  it("combines priceFetcher + inventoryChecker + asyncTaxProvider", async () => {
    const cart = new Cart();
    cart.add(productA, 2);
    cart.add(productB, 1);

    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn()
        .mockResolvedValueOnce(1200) // a → 1200
        .mockResolvedValueOnce(3000), // b → 3000
    };
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 100 }),
    };
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };

    const result = await cart.checkout({ priceFetcher, inventoryChecker, asyncTaxProvider });
    // subtotal: 1200*2 + 3000*1 = 5400, tax: floor(5400 * 0.1) = 540
    expect(result.totals.subtotalCents).toBe(5400);
    expect(result.totals.taxCents).toBe(540);
  });

  it("generates default error message when no reason provided", async () => {
    const cart = new Cart();
    cart.add(productA, 5);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: false,
      } satisfies InventoryDecision),
    };
    try {
      await cart.checkout({ inventoryChecker });
    } catch (e) {
      expect(e).toBeInstanceOf(InventoryError);
      expect((e as InventoryError).message).toContain("insufficient stock");
      expect((e as InventoryError).productId).toBe("a");
    }
  });

  it("checks inventory for each line sequentially", async () => {
    const cart = new Cart();
    cart.add(productA, 1);
    cart.add(productB, 1);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn()
        .mockResolvedValueOnce({ available: true, availableQuantity: 10 })
        .mockResolvedValueOnce({ available: false, reason: "discontinued" }),
    };
    await expect(cart.checkout({ inventoryChecker })).rejects.toThrow("discontinued");
    expect(inventoryChecker.check).toHaveBeenCalledTimes(2);
  });
});

