    const result = await cart.checkout({ priceFetcher, inventoryChecker, asyncTaxProvider });
    // subtotal: 1200*2 + 3000*1 = 5400, tax: floor(5400 * 0.1) = 540
    expect(result.totals.subtotalCents).toBe(5400);
    expect(result.totals.taxCents).toBe(540);
  });

  it("generates default error message when no reason provided", async () => {
    const cart = new Cart();
